function decodeCell(code) {
  const index = CELL_ALPHABET.indexOf(code);
  if (index < 0 || index >= 63) throw new TypeError(`invalid catalog cell: ${code}`);
  return Object.freeze([index % 7, Math.floor(index / 7)]);
}

function decodeRoute(encoded) {
  const [pathText, gateText, laneText = ''] = encoded.split(',');
  if (!pathText || !gateText || gateText.length !== 2) throw new TypeError('invalid catalog route');
  const path = Object.freeze([...pathText].map(decodeCell));
  const gate = Object.freeze({ side: SIDE_BY_CODE[gateText[0]], line: Number(gateText[1]) });
  if (!gate.side || !Number.isInteger(gate.line)) throw new TypeError('invalid catalog gate');
  if (laneText.length % 2 !== 0) throw new TypeError('invalid catalog lanes');
  const lanes = [];
  for (let index = 0; index < laneText.length; index += 2) {
    const [x, y] = decodeCell(laneText[index]);
    const direction = DIRECTION_BY_CODE[laneText[index + 1]];
    if (!direction) throw new TypeError('invalid catalog lane direction');
    lanes.push(Object.freeze({ x, y, direction }));
  }
  return Object.freeze({ path, gate, lanes: Object.freeze(lanes) });
}

function decodeTemplate(profileId, encoded, index) {
  const meta = PROFILE_META[profileId];
  if (!meta) throw new TypeError(`unknown catalog profile: ${profileId}`);
  return Object.freeze({
    id: `${profileId}-t${String(index).padStart(2, '0')}`,
    profileId,
    counts: meta.counts,
    expectedOptimalSwipes: meta.expectedOptimalSwipes,
    routes: Object.freeze(encoded.split(';').map(decodeRoute)),
  });
}

export const GENERATOR_V3_TEMPLATE_CATALOG = Object.freeze(
  Object.entries(ENCODED_TEMPLATES).flatMap(([profileId, templates]) => (
    templates.map((encoded, index) => decodeTemplate(profileId, encoded, index))
  )),
);
